pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        // admissible domain: amounts and extra padding kept small/sane
        amount = bound(amount, 1, 1e24);
        extra = bound(extra, 0, 1e24);

        // fund the contract with exactly `amount` ether (this contract is c's owner,
        // since owner = msg.sender at deployment)
        vm.deal(address(c), amount);
        // give the owner (this test contract) funds so the outgoing transfer succeeds
        vm.deal(address(this), 1e30);

        uint256 before = address(c).balance;
        vm.assume(before >= amount);

        // the deciding call is `withdraw` with the fuzzed amount
        vm.prank(c.owner());
        c.withdraw(amount);

        // single universal assertion: balance drops by exactly `amount`
        assertTrue(address(c).balance == before - amount);
    }
}

