pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 nDeposits, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        nDeposits = bound(nDeposits, 1, 50);
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.startPrank(actor);
        for (uint256 i = 0; i < nDeposits; i++) {
            (bool ok, ) = address(c).call{value: amount / nDeposits}("");
            require(ok);
        }
        vm.stopPrank();
        uint256 before = c.depositsCount();
        vm.deal(address(this), 1);
        vm.prank(c.owner());
        c.withdrawAll();
        assertEq(c.depositsCount(), before, "guarded call must not bump depositsCount");
    }
}

