contract InvMutTest {
    C c;
    uint got;

    constructor(C _c) { c = _c; }

    receive() external payable { got++; }

    function test(uint amount) public {
        require(amount > 0);
        require(c.owner() != address(this));
        require(address(this).balance >= amount);

        // Fund c through its payable fallback.
        (bool okF, ) = address(c).call{value: amount}("");
        require(okF);

        // A non-owner attempts to move c's funds to this contract.
        c.sendMoney(address(this), amount);

        // On P this line is unreachable (sendMoney reverted the whole tx).
        // On M the funds arrive, so got == 1 and the assert fails.
        assert(got == 0);
    }
}

